select sum(p.id) over (order by p.id rows between 1 preceding and 1 following) as rows_around, sum(p.id) over (order by p.id rows between current row and unbounded following) as rest, sum(p.id) over (order by p.id rows unbounded preceding) as running, min(p.id) over (order by p.user_id range between unbounded preceding and current row) as least_id, avg(p.id) over (order by p.user_id range between current row and unbounded following) as mean from posts p
